package com.example.bmmoney;
import android.content.*;import android.graphics.Color;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.bmmoney.remote.FirebaseSyncManager;import java.util.*;
public class SettingsActivity extends AppCompatActivity{private LinearLayout paletteList;private EditText edtCoolorsUrl;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_settings);ThemeManager.apply(this);paletteList=findViewById(R.id.paletteList);edtCoolorsUrl=findViewById(R.id.edtCoolorsUrl);buildPalettes();setupUrlImport();findViewById(R.id.btnSyncNow).setOnClickListener(v->{new FirebaseSyncManager(this).uploadAllLocal();Toast.makeText(this,"Đã đẩy dữ liệu local lên cloud",Toast.LENGTH_SHORT).show();});setupNav();}private void buildPalettes(){paletteList.removeAllViews();for(String[] p:ThemeManager.PALETTES)addPaletteRow(p);}private void addPaletteRow(String[] p){TextView row=new TextView(this);row.setText(p[0]+"\n"+p[1]+"  "+p[2]+"  "+p[3]+"  "+p[4]+"  "+p[5]);row.setTextColor(Color.parseColor("#283618"));row.setTextSize(15);row.setPadding(18,18,18,18);row.setBackgroundResource(R.drawable.bg_panel_new);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,12);row.setLayoutParams(lp);row.setOnClickListener(v->{ThemeManager.savePalette(this,p);saveThemeOnline(p);ThemeManager.apply(this);Toast.makeText(this,"Đã đổi sang bộ màu "+p[0],Toast.LENGTH_SHORT).show();});paletteList.addView(row);}private void setupUrlImport(){String saved=getSharedPreferences("settings",MODE_PRIVATE).getString("coolors_url","");edtCoolorsUrl.setText(saved);edtCoolorsUrl.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int b,int c){getSharedPreferences("settings",MODE_PRIVATE).edit().putString("coolors_url",s.toString()).apply();parseCoolorsUrl(s.toString());}});}private void parseCoolorsUrl(String url){int idx=url.lastIndexOf("/");if(idx<0)return;String tail=url.substring(idx+1).trim();if(!tail.contains("-"))return;String[] raw=tail.split("-");if(raw.length<5)return;String[] p=new String[]{"Coolors URL","#"+raw[0],"#"+raw[1],"#"+raw[2],"#"+raw[3],"#"+raw[4]};try{for(int i=1;i<=5;i++)Color.parseColor(p[i]);ThemeManager.savePalette(this,p);ThemeManager.apply(this);}catch(Exception ignored){}}private void saveThemeOnline(String[] p){Map<String,Object> theme=new HashMap<>();theme.put("name",p[0]);theme.put("bg1",p[1]);theme.put("bg2",p[2]);theme.put("primary",p[3]);theme.put("secondary",p[4]);theme.put("accent",p[5]);new FirebaseSyncManager(this).saveTheme(theme);}private void setupNav(){findViewById(R.id.navHome).setOnClickListener(v->startActivity(new Intent(this,MainActivity.class)));findViewById(R.id.navAdd).setOnClickListener(v->startActivity(new Intent(this,AddTransactionActivity.class)));findViewById(R.id.navReport).setOnClickListener(v->startActivity(new Intent(this,ReportActivity.class)));findViewById(R.id.navSearch).setOnClickListener(v->startActivity(new Intent(this,SearchActivity.class)));findViewById(R.id.navSettings).setOnClickListener(v->{});}}
